head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF35119.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    txb_reg_emp_nm.setValue(js_emp_nm);
    // 벌점부과유형  셋팅
    dts_CautnActRsn.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=CAUTN_ACT_RSN_CD";
    dts_CautnActRsn.Reset();
};
scwin.fn_save = function() {
    // 등록
    //초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd == "") {
        $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }


    /*		
    		if(getObjectValue(txb_file_nm) == "" ) {
    			alert("첨부파일을  입력해주세요");
    			inf_find.focus();
    			return;
    		}
    */

    if ($c.stf.getObjectValue(txb_file_nm).length > 80) {
        $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "RPT_DD", $c.stf.getObjectValue(edt_rpt_dd));
    dts_file_save.setCellData(1, "CAUTN_ACT_RSN_CD", $c.stf.getObjectValue(cmb_cautn_act_rsn));
    dts_file_save.setCellData(1, "EMP_NO", js_emp_no);
    dts_file_save.setCellData(1, "END_DD", $c.stf.getObjectValue(edt_end_dd));
    dts_file_save.setCellData(1, "ATTACH_FILE_NM", $c.stf.getObjectValue(txb_file_nm));
    dts_file_save.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));
    var vAnswer;
    vAnswer = confirm('주의조치 정보를 저장 하시겠습니까?');
    if (vAnswer == true) {
        trs_Save.Action = "/PenaltyImposition.do?method=registerCautnActRsn&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_file_save,I:pFile=dts_fileData)";
        trs_Save.Post();
    }
};



//PopupCalendar에서 호출함. 공통으로 사용해서~ 껍질만 들고옴. 이 화면에서는 만료일 구해오는게 하나라 gubunPNLT 의미 없음
scwin.checkGraceInfo = function(gubunPNLT) {
    scwin.getIn6months();
};
scwin.getIn6months = function() {
    dts_in_6_months.DataID = "/PenaltyImposition.do?method=getIn6months&inputMessageId=CAUTN_ACT_DTL_INOUT" + "&outputMessageId=CAUTN_ACT_DTL_INOUT" + "&RPT_DD=" + $c.stf.getObjectValue(edt_rpt_dd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_in_6_months.reset();
};



//달력일로 변경old 스크립트로 호출하면 2022-08-09 +6개월 하면 2023-03-01 이 나오는데 2022-2-02-28로 나와야 한다고해서 오라클 콜로 바꿈.
scwin.getIn60days_old = function() {
    var rpt_dd = $c.stf.getObjectValue(edt_rpt_dd);
    var inp_year = rpt_dd.substr(0, 4);
    var inp_month = rpt_dd.substr(4, 2) - 1;
    var inp_day = rpt_dd.substr(6, 2);
    var date = new Date(inp_year, inp_month, inp_day);
    date.setMonth(date.getMonth() + 6);
    var month = (date.getMonth() + 1);
    if ((month + "").length == 1) month = "0" + month;
    var day = date.getDate();
    if ((day + "").length == 1) day = "0" + day;
    edt_end_dd.setValue(date.getFullYear() + "" + month + "" + day);
};
scwin.inf_find_OnClick = function() {
    dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
    txb_file_nm.setValue(inf_find.getValue());
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("등록 성공");
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("등록 실패");
    $c.win.alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.img_save_onclick = function() {
    scwin.fn_save();
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //showObj(txb_isurcd, false);	// 히든처리!
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(penel_1);
    scwin.fn_SetCode();

    // 가우스헤더 셋팅
    dts_file_save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CAUTN_ACT_DTL_INOUT";
    dts_file_save.reset();

    // 파일: 가우스헤더 셋팅

    //dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_fileData.insertRow();
};
scwin.img_rpt_dd_onclick = function() {
    popUpCalendar3(edt_rpt_dd);
};
scwin.dts_in_6_months_OnLoadCompleted = function(rowcount) {
    edt_end_dd.setValue(dts_in_6_months.getCellData(1, "END_DD"));
};
scwin.img_end_dd_onclick = function() {
    popUpCalendar2(edt_end_dd);
};
